def transform(grid):
    from collections import Counter

    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    marker = min(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    if not points:
        return out
    min_r = min(r for r, _ in points)
    max_r = max(r for r, _ in points)
    min_c = min(c for _, c in points)
    max_c = max(c for _, c in points)

    def fill_cell(r, c):
        if out[r][c] != marker:
            out[r][c] = 2

    # Complete the outer rectangle around the marker pattern.
    for c in range(min_c, max_c + 1):
        fill_cell(min_r, c)
        fill_cell(max_r, c)
    for r in range(min_r, max_r + 1):
        fill_cell(r, min_c)
        fill_cell(r, max_c)

    # Complete dense interior alignments across the same bounding box.
    for r in range(min_r + 1, max_r):
        if sum(grid[r][c] == marker for c in range(w)) >= 6:
            for c in range(min_c, max_c + 1):
                fill_cell(r, c)
    for c in range(min_c + 1, max_c):
        if sum(grid[r][c] == marker for r in range(h)) >= 6:
            for r in range(min_r, max_r + 1):
                fill_cell(r, c)
    return out
